<?php
declare(strict_types=1);
namespace FMonitor2\InstallationProcess;

final class MariaDbPilotSnapshotImporter
{
 public function __construct(private readonly \mysqli$db,private readonly string$processPrefix,private readonly string$legacyPrefix){foreach([$processPrefix,$legacyPrefix]as$p)MariaDbSchemaInspector::validateTablePrefix($p);}
 public function import(string$path,string$expectedSha,string$now):array
 {
  if(!is_file($path)||(fileperms($path)&0777)!==0600||preg_match('/^[0-9a-f]{64}$/D',$expectedSha)!==1||!hash_equals($expectedSha,hash_file('sha256',$path)))throw new \DomainException('SNAPSHOT_INTEGRITY_INVALID');$snapshot=json_decode(file_get_contents($path),true,flags:JSON_THROW_ON_ERROR);$objects=$this->validate($snapshot);$valid=[];$missing=[];foreach($objects as$o){if(trim((string)$o['address'])===''||trim((string)$o['entrance'])===''||trim((string)$o['registrationNumber'])===''){$missing[]=(int)$o['id'];continue;}$valid[]=$o;}$this->preflight($valid,$snapshot);$this->stage($valid);$ids=array_map(fn($o)=>(int)$o['id'],$valid);$cases=(new PilotCaseImporter($this->db,$this->processPrefix,$this->legacyPrefix))->import($ids,$now);if(isset($cases['rejected']))throw new \DomainException('CASE_IMPORT_REJECTED');$detail=$this->details($valid,$snapshot,$now);$template=$this->template($snapshot,$now);return['snapshotObjects'=>count($objects),'identified'=>count($valid),'missingIdentification'=>$missing,'cases'=>$cases,'details'=>$detail,'template'=>$template];
 }
 private function validate(array$s):array
 {
  if(($s['schemaVersion']??null)!=='manual-pilot-source-snapshot-v1'||!is_array($s['objects']??null)||!array_key_exists('plannedDateFilter',$s['eligibility']??[])||$s['eligibility']['plannedDateFilter']!==null)throw new \DomainException('SNAPSHOT_SCHEMA_INVALID');$ids=[];foreach($s['objects']as$o){$id=filter_var($o['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false||isset($ids[$id])||($o['eligibilityProof']??null)!==['actualOpening'=>false,'checklistActivity'=>false]||!is_array($o['plannedDates']??null)||!is_array($o['technical']??null)||($o['controlEngineerUserId']??null)!==null)throw new \DomainException('SNAPSHOT_OBJECT_INVALID');foreach(['start','adjustedStart','adjustedFinish','plannedFinish','legacyFinish']as$k)if(!array_key_exists($k,$o['plannedDates']))throw new \DomainException('SNAPSHOT_OBJECT_INVALID');foreach(['floors','weight','speed','pittype','pitmaterial','paired']as$k)if(!isset($o['technical'][$k])||!array_key_exists('raw',$o['technical'][$k])||!array_key_exists('display',$o['technical'][$k]))throw new \DomainException('SNAPSHOT_OBJECT_INVALID');$ids[$id]=true;}$t=$s['checklistTemplate']??null;if(!is_array($t)||($t['counts']??null)!==['parts'=>8,'definitions'=>42,'totalShare'=>100]||!is_array($t['payload']['definitions']??null))throw new \DomainException('SNAPSHOT_TEMPLATE_INVALID');$work=0;$doc=0;$n=0;foreach($t['payload']['definitions']as$d){(int)$d['id']===42?$doc+=(int)$d['share']:$work+=(int)$d['share'];if((int)$d['id']!==42)$n++;}if($n!==41||$work!==85||$doc!==15)throw new \DomainException('SNAPSHOT_TEMPLATE_INVALID');return$s['objects'];
 }
 private function preflight(array$objects,array$s):void
 {
  foreach($objects as$o){$id=(int)$o['id'];$r=$this->db->query("SELECT ordadr_address,entrance,regnumber,workdatestart,workdatestartadjusted,workdateendadjusted,plan_finish_date,workdatefinish,responsstroicontrol FROM `{$this->legacyPrefix}fm_maintable` WHERE id=$id")->fetch_assoc();if($r!==null){$expected=[$o['address'],$o['entrance'],$o['registrationNumber'],$o['plannedDates']['start'],$o['plannedDates']['adjustedStart'],$o['plannedDates']['adjustedFinish'],$o['plannedDates']['plannedFinish'],null,null];if(array_values($r)!==array_map(fn($v)=>$v===null?null:(string)$v,$expected))throw new \DomainException('MIRROR_CONFLICT');}$material=['schemaVersion'=>'technical-object-detail-v1','objectId'=>$id,'fields'=>$o['technical']];$detailHash=hash('sha256',json_encode($material,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$detail=$this->db->query("SELECT content_sha256 FROM `{$this->processPrefix}fm2_pilot_object_details` WHERE object_id=$id")->fetch_assoc();if($detail!==null&&!hash_equals($detailHash,$detail['content_sha256']))throw new \DomainException('DETAIL_CONFLICT');}
  $hash=(string)$s['checklistTemplate']['contentSha256'];$q=$this->db->prepare("SELECT payload_json FROM `{$this->processPrefix}fm2_checklist_template_snapshots` WHERE content_sha256=?");$q->bind_param('s',$hash);$q->execute();$r=$q->get_result()->fetch_assoc();if($r!==null&&!hash_equals($hash,hash('sha256',(string)$r['payload_json'])))throw new \DomainException('TEMPLATE_CONFLICT');
 }
 private function stage(array$objects):void
 {
  $this->db->begin_transaction();try{$q=$this->db->prepare("INSERT INTO `{$this->legacyPrefix}fm_maintable`(id,ordadr_address,entrance,regnumber,workdatestart,workdatestartadjusted,workdateendadjusted,plan_finish_date,workdatefinish,ptoactdate,responsstroicontrol,floors,weight,speed,pittype,pitmaterial,paired)VALUES(?,?,?,?,?,?,?,?,NULL,NULL,NULL,?,?,?,?,?,?)");foreach($objects as$o){$id=(int)$o['id'];if($this->db->query("SELECT 1 FROM `{$this->legacyPrefix}fm_maintable` WHERE id=$id FOR UPDATE")->fetch_row()!==null)continue;$p=$o['plannedDates'];$t=$o['technical'];$v=[$o['address'],$o['entrance'],$o['registrationNumber'],$p['start'],$p['adjustedStart'],$p['adjustedFinish'],$p['plannedFinish'],$t['floors']['raw'],$t['weight']['raw'],$t['speed']['raw'],$t['pittype']['raw'],$t['pitmaterial']['raw'],$t['paired']['raw']];$q->bind_param('isssssssssssss',$id,...$v);$q->execute();}$this->db->commit();}catch(\Throwable$e){$this->db->rollback();throw$e;}
 }
 private function details(array$objects,array$s,string$now):array
 {
  $created=0;$present=0;$this->db->begin_transaction();try{$q=$this->db->prepare("INSERT INTO `{$this->processPrefix}fm2_pilot_object_details` VALUES(?,?,?,?,?)");foreach($objects as$o){$material=['schemaVersion'=>'technical-object-detail-v1','objectId'=>(int)$o['id'],'fields'=>$o['technical']];$hash=hash('sha256',json_encode($material,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$id=(int)$o['id'];$r=$this->db->query("SELECT content_sha256 FROM `{$this->processPrefix}fm2_pilot_object_details` WHERE object_id=$id FOR UPDATE")->fetch_assoc();if($r!==null){if(!hash_equals($hash,$r['content_sha256']))throw new \DomainException('DETAIL_CONFLICT');$present++;continue;}$json=json_encode($material,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$version='technical-object-detail-v1';$q->bind_param('issss',$id,$version,$hash,$json,$now);$q->execute();$created++;}$this->db->commit();return compact('created','present');}catch(\Throwable$e){$this->db->rollback();throw$e;}
 }
 private function template(array$s,string$now):array
 {
  $t=$s['checklistTemplate'];$hash=$t['contentSha256'];$q=$this->db->prepare("SELECT id FROM `{$this->processPrefix}fm2_checklist_template_snapshots` WHERE content_sha256=?");$q->bind_param('s',$hash);$q->execute();$r=$q->get_result()->fetch_assoc();if($r!==null)return['created'=>false,'snapshotId'=>(int)$r['id']];$payload=json_encode($t['payload'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$captured=str_replace('T',' ',substr((string)$s['capturedAtUtc'],0,19));$created=str_replace('T',' ',substr($now,0,19));$version=$t['payload']['snapshotVersion'];$scope='active_baseline_and_future_native_only';$source='private_manual_pilot_snapshot';$q=$this->db->prepare("INSERT INTO `{$this->processPrefix}fm2_checklist_template_snapshots`(snapshot_version,captured_at,valid_from,validity_scope,source_label,content_sha256,payload_json,created_at)VALUES(?,?,?,?,?,?,?,?)");$q->bind_param('ssssssss',$version,$captured,$captured,$scope,$source,$hash,$payload,$created);$q->execute();return['created'=>true,'snapshotId'=>(int)$q->insert_id];
 }
 private function date(mixed$v):?string{if($v===null)return null;$v=trim((string)$v);if($v===''||str_starts_with($v,'0000-00-00'))return null;return preg_match('/^\d{4}-\d{2}-\d{2}/D',$v)===1?substr($v,0,10):null;}
}
